// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

interface IModelRegistry {
    function getModelHandler(bytes32 modelId) external view returns (address);
    function isModelActive(bytes32 modelId) external view returns (bool);
}

interface IInferenceHandler {
    function runInference(bytes calldata input, bytes32 nonce) external returns (bytes memory);
    function getModelMetadata() external view returns (bytes memory);
}

contract MLInferenceServer is AccessControl, ReentrancyGuard {
    bytes32 public constant ORACLE_ROLE = keccak256("ORACLE_ROLE");
    bytes32 public constant SERVICE_ROLE = keccak256("SERVICE_ROLE");

    IModelRegistry public immutable modelRegistry;

    mapping(bytes32 => uint256) public inferenceNonces;
    mapping(address => mapping(bytes32 => bool)) public serviceAuthorizations;
    mapping(bytes32 => address) private _handlerOverrides;

    event InferenceRequested(bytes32 indexed modelId, address indexed requester, bytes32 nonce);
    event InferenceCompleted(bytes32 indexed modelId, bytes32 nonce, bytes result);
    event HandlerOverrideSet(bytes32 indexed modelId, address handler);

    struct AuthToken {
        address service;
        bytes32 modelId;
        uint256 expiry;
        bytes32 commitment;
    }

    constructor(address _registry, address _admin) {
        modelRegistry = IModelRegistry(_registry);
        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(ORACLE_ROLE, _admin);
    }

    function authorizeService(address service, bytes32 modelId) external onlyRole(DEFAULT_ADMIN_ROLE) {
        serviceAuthorizations[service][modelId] = true;
    }

    function setHandlerOverride(bytes32 modelId, address handler) external onlyRole(ORACLE_ROLE) {
        _handlerOverrides[modelId] = handler;
        emit HandlerOverrideSet(modelId, handler);
    }

    function resolveHandler(bytes32 modelId) public view returns (address) {
        address override_ = _handlerOverrides[modelId];
        if (override_ != address(0)) {
            return override_;
        }
        return modelRegistry.getModelHandler(modelId);
    }

    function _validateAuthToken(AuthToken calldata token, bytes calldata signature) internal view returns (bool) {
        require(token.expiry > block.timestamp, "Token expired");
        require(serviceAuthorizations[token.service][token.modelId], "Service not authorized");

        bytes32 tokenHash = keccak256(abi.encodePacked(
            token.service,
            token.modelId,
            token.expiry,
            token.commitment
        ));

        address signer = _recoverSigner(tokenHash, signature);
        return hasRole(SERVICE_ROLE, signer);
    }

    function requestInference(
        bytes32 modelId,
        bytes calldata inputData,
        AuthToken calldata authToken,
        bytes calldata authSignature
    ) external nonReentrant returns (bytes memory) {
        require(_validateAuthToken(authToken, authSignature), "Invalid auth");
        require(authToken.modelId == modelId, "Model mismatch");
        require(modelRegistry.isModelActive(modelId), "Model inactive");

        bytes32 nonce = bytes32(inferenceNonces[modelId]++);
        emit InferenceRequested(modelId, msg.sender, nonce);

        address handler = resolveHandler(modelId);
        require(handler != address(0), "No handler");

        bytes memory result = _executeInference(handler, inputData, nonce);
        emit InferenceCompleted(modelId, nonce, result);

        return result;
    }

    function _executeInference(
        address handler,
        bytes calldata inputData,
        bytes32 nonce
    ) internal returns (bytes memory) {
        // Construct the call using delegatecall for gas efficiency
        // Handler executes in this contract's context for state access
        (bool success, bytes memory result) = handler.delegatecall(
            abi.encodeWithSelector(
                IInferenceHandler.runInference.selector,
                inputData,
                nonce
            )
        );
        require(success, "Inference failed");
        return abi.decode(result, (bytes));
    }

    function batchInference(
        bytes32[] calldata modelIds,
        bytes[] calldata inputs,
        AuthToken[] calldata tokens,
        bytes[] calldata signatures
    ) external nonReentrant returns (bytes[] memory results) {
        require(modelIds.length == inputs.length, "Length mismatch");
        require(modelIds.length == tokens.length, "Length mismatch");

        results = new bytes[](modelIds.length);
        for (uint256 i = 0; i < modelIds.length; i++) {
            require(_validateAuthToken(tokens[i], signatures[i]), "Invalid auth");
            require(tokens[i].modelId == modelIds[i], "Model mismatch");

            address handler = resolveHandler(modelIds[i]);
            bytes32 nonce = bytes32(inferenceNonces[modelIds[i]]++);
            results[i] = _executeInference(handler, inputs[i], nonce);
        }
    }

    function _recoverSigner(bytes32 hash, bytes calldata sig) internal pure returns (address) {
        require(sig.length == 65, "Invalid signature length");
        bytes32 r;
        bytes32 s;
        uint8 v;
        assembly {
            r := calldataload(sig.offset)
            s := calldataload(add(sig.offset, 32))
            v := byte(0, calldataload(add(sig.offset, 64)))
        }
        return ecrecover(keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", hash)), v, r, s);
    }
}
